# ---------------------------------------------------------------- build the three files
base_en = json.load(open('content/26.1.0/en.json'))
names_en = [r['name'] for r in base_en['components']['rows']]
ORDER_NEW = ['block_page', 'content', 'sandbox', 'analytics', 'dashboard', 'plots', 'logviewer']
ORDER_IMP = ['defaults', 'wan', 'youtube', 'logs']
for lang in L:
    d = copy.deepcopy(json.load(open('content/26.1.0/%s.json' % lang)))
    d['title'] = 'Nexwall Firewall 26.1.1'
    d['summary'] = SUMMARY[lang]
    d['overview'] = OVERVIEW[lang]
    for row in d['at_a_glance']:
        if row['value'] == '26.1.0':
            row['value'] = '26.1.1'
        elif 'table' in row['value'].lower() or row['value'] in ('Stable release', 'Versión estable', 'Versão estável'):
            row['value'] = GLANCE_STATUS[lang]
    for sec in d['sections']:
        if sec['id'] == 'whats-new':
            sec['items'] = [{'tag': 'new', 'title': NEW[k][lang][0], 'body': NEW[k][lang][1]} for k in ORDER_NEW]
        elif sec['id'] == 'improvements':
            sec['items'] = [{'tag': 'improved', 'title': IMPROVED[k][lang][0], 'body': IMPROVED[k][lang][1]} for k in ORDER_IMP]
    rows = d['components']['rows']
    for idx, en_name in enumerate(names_en):
        if idx >= len(rows):
            break
        if en_name == 'Image':
            rows[idx]['version'] = '26.1.1'
        elif en_name == 'Firmware sources':
            rows[idx]['version'] = 'main (set when the image is built)'
        elif en_name in COMPONENTS:
            version, note = COMPONENTS[en_name]
            rows[idx]['version'] = version
            if note:
                rows[idx]['note'] = note[lang]
    date, title, text = TIMELINE[lang]
    d['timeline']['entries'] = [{'date': date, 'title': title, 'text': text}]
    os.makedirs('content/26.1.1', exist_ok=True)
    json.dump(d, open('content/26.1.1/%s.json' % lang, 'w'), ensure_ascii=False, indent=2)
    open('content/26.1.1/%s.json' % lang, 'a').write('\n')

